mapper.select:
select a.slip_id ,a.slip_date ,a.slip_type ,a.description ,a.resolution_id ,b.budget_id as budget_code ,b.total_amount as total_amount ,a.status ,a.created_by ,a.confirmed_by ,a.confirmed_at from tb_slip_header a left outer join tb_expense_resolutions b on a.resolution_id = b.no where 1=1
and a.slip_id = #{slip_id}
order by slip_id desc

mapper.update:
update tb_slip_header
   set status = '1'
      ,confirmed_by = #{confirmed_by}
      ,confirmed_at = now()
 where slip_id = #{slip_id}

update tb_slip_header
   set status = '3'
 where slip_id = #{slip_id}

update tb_slip_header
   set status = '2'
      ,confirmed_by = #{confirmed}
      ,confirmed_at = now()
 where slip_id = #{slip_id}

update tb_budget_category
   set amount = amount - #{amt}
 where 1=1
   and code = #{budget_code}
